insert into public.products (id, category_id, name, slug, short_description, description, ingredients, origin, storage_instructions, shelf_life, status, is_featured, is_bestseller, search_text) values ('87ca1184-e542-4f2f-a890-a606cce360e9', 'ba559c3e-c1bb-4c30-a200-1ec315831e87', 'Organic Raw Forest Honey', 'organic-raw-forest-honey', 'Unheated multifloral honey with a deep, resinous finish.', 'Collected from mixed forest forage and packed without heating. The texture is naturally thick; crystals may form over time — a sign it has not been ultra-filtered. Stir gently and use as you would any raw honey.', 'Organic raw honey.', NULL, 'Store at room temperature, away from direct sun. Do not refrigerate.', '18 months', 'published', TRUE, TRUE, 'organic raw forest honey unheated multifloral honey with a deep, resinous finish. organic raw honey.') on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, is_featured = excluded.is_featured, is_bestseller = excluded.is_bestseller, search_text = excluded.search_text;
insert into public.products (id, category_id, name, slug, short_description, description, ingredients, origin, storage_instructions, shelf_life, status, is_featured, is_bestseller, search_text) values ('266d6146-85df-4335-a6c8-0750e6d5071f', '2c1fe596-6727-40c9-a911-9ee50ae106ec', 'Cold Pressed Groundnut Oil', 'cold-pressed-groundnut-oil', 'Wooden-ghani pressed peanuts. Clean nut aroma, high smoke point.', 'Single-ingredient oil pressed in small batches. No hexane, no blending with refined oils. Suitable for everyday tempering and shallow frying.', 'Organic groundnuts (peanuts).', NULL, 'Keep sealed, away from heat. Use within 90 days of opening.', '9 months', 'published', TRUE, TRUE, 'cold pressed groundnut oil wooden-ghani pressed peanuts. clean nut aroma, high smoke point. organic groundnuts (peanuts).') on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, is_featured = excluded.is_featured, is_bestseller = excluded.is_bestseller, search_text = excluded.search_text;
insert into public.products (id, category_id, name, slug, short_description, description, ingredients, origin, storage_instructions, shelf_life, status, is_featured, is_bestseller, search_text) values ('f838d3e0-89a6-4a3e-ad21-31bcb8c98c84', 'bfae1eb7-8fdd-4753-aaa9-9b573797c431', 'Organic Turmeric Powder', 'organic-turmeric-powder', 'High-curcumin grind. Warm, earthy, slightly bitter.', 'Rhizomes are solar-dried and stone-ground. Colour is naturally deep; no added colour. Use in dals, milk, and marinades.', 'Organic turmeric rhizome.', NULL, 'Airtight, away from moisture and light.', '12 months', 'published', TRUE, FALSE, 'organic turmeric powder high-curcumin grind. warm, earthy, slightly bitter. organic turmeric rhizome.') on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, is_featured = excluded.is_featured, is_bestseller = excluded.is_bestseller, search_text = excluded.search_text;
insert into public.products (id, category_id, name, slug, short_description, description, ingredients, origin, storage_instructions, shelf_life, status, is_featured, is_bestseller, search_text) values ('297e651f-02d5-4844-a16c-d5bd98cff58c', 'bfae1eb7-8fdd-4753-aaa9-9b573797c431', 'Organic Black Pepper', 'organic-black-pepper', 'Bold peppercorns with a slow, citrus heat.', 'Sun-dried on the vine-side estates. Sold whole so you can crack fresh. The aroma is pine and orange peel rather than dusty heat.', 'Organic black peppercorns.', NULL, 'Airtight glass, away from steam.', '24 months', 'published', FALSE, TRUE, 'organic black pepper bold peppercorns with a slow, citrus heat. organic black peppercorns.') on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, is_featured = excluded.is_featured, is_bestseller = excluded.is_bestseller, search_text = excluded.search_text;
insert into public.products (id, category_id, name, slug, short_description, description, ingredients, origin, storage_instructions, shelf_life, status, is_featured, is_bestseller, search_text) values ('64a51abc-ae86-4df2-a461-e227bf18c406', '1ee84b1c-d0af-4ad8-a70b-9ca76346e3a1', 'Organic Foxtail Millet', 'organic-foxtail-millet', 'Light, quick-cooking millet for pongal, upma, and bowls.', 'Dehulled foxtail millet with a mild, nutty flavour. Rinse twice. Cooks in about 12 minutes. A everyday grain, not a novelty.', 'Organic foxtail millet (Setaria italica).', NULL, 'Cool, dry cupboard. Refrigerate in humid months.', '10 months', 'published', TRUE, FALSE, 'organic foxtail millet light, quick-cooking millet for pongal, upma, and bowls. organic foxtail millet (setaria italica).') on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, is_featured = excluded.is_featured, is_bestseller = excluded.is_bestseller, search_text = excluded.search_text;
insert into public.products (id, category_id, name, slug, short_description, description, ingredients, origin, storage_instructions, shelf_life, status, is_featured, is_bestseller, search_text) values ('56dc80a5-bcf0-4f0a-a3f6-127bf73c84e1', '1ee84b1c-d0af-4ad8-a70b-9ca76346e3a1', 'Organic Little Millet', 'organic-little-millet', 'Soft-cooking millet that stands in for rice.', 'Smaller grain, gentler bite. Works in lemon rice, khichdi, and porridge. Grown in rain-fed plots without synthetic pesticides.', 'Organic little millet (Panicum sumatrense).', NULL, 'Airtight tin, away from moisture.', '10 months', 'published', FALSE, FALSE, 'organic little millet soft-cooking millet that stands in for rice. organic little millet (panicum sumatrense).') on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, is_featured = excluded.is_featured, is_bestseller = excluded.is_bestseller, search_text = excluded.search_text;
insert into public.products (id, category_id, name, slug, short_description, description, ingredients, origin, storage_instructions, shelf_life, status, is_featured, is_bestseller, search_text) values ('b2406c89-501a-4bb7-a318-32a2a82610f9', 'ecd1055a-ab50-484c-ad6b-67f62a136c3e', 'Organic Cashews', 'organic-cashews', 'W240 whole kernels. Creamy, lightly sweet, never oiled.', 'Steam-opened kernels, graded by hand. No added oil or salt. Use as they are, or soak for milks and gravies.', 'Organic cashew kernels.', NULL, 'Refrigerate after opening. Use within 60 days.', '8 months', 'published', TRUE, TRUE, 'organic cashews w240 whole kernels. creamy, lightly sweet, never oiled. organic cashew kernels.') on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, is_featured = excluded.is_featured, is_bestseller = excluded.is_bestseller, search_text = excluded.search_text;
insert into public.products (id, category_id, name, slug, short_description, description, ingredients, origin, storage_instructions, shelf_life, status, is_featured, is_bestseller, search_text) values ('7a96cd7f-3dc4-4992-aeb5-f4d823f42a89', 'ecd1055a-ab50-484c-ad6b-67f62a136c3e', 'Organic Almonds', 'organic-almonds', 'Long almonds, raw and unblanched.', 'Whole natural almonds with skin on. Crunchy, clean finish. No roasting oil. A daily handful, or soak overnight.', 'Organic raw almonds.', NULL, 'Cool and dry. Refrigerate in summer.', '8 months', 'published', FALSE, FALSE, 'organic almonds long almonds, raw and unblanched. organic raw almonds.') on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, is_featured = excluded.is_featured, is_bestseller = excluded.is_bestseller, search_text = excluded.search_text;
insert into public.products (id, category_id, name, slug, short_description, description, ingredients, origin, storage_instructions, shelf_life, status, is_featured, is_bestseller, search_text) values ('caca444f-2025-4424-a731-9cca6a09cae6', 'b1a95a14-b415-4541-aa6c-853c646102b6', 'Organic Herbal Evening Tea', 'organic-herbal-evening-tea', 'Tulsi, lemongrass, and ginger. Caffeine-free.', 'A quiet evening blend. Leaves are shade-dried and cut, not powdered into dust. Steep 4 minutes covered.', 'Organic tulsi, lemongrass, dried ginger, mint.', NULL, 'Airtight, away from spices.', '14 months', 'published', TRUE, FALSE, 'organic herbal evening tea tulsi, lemongrass, and ginger. caffeine-free. organic tulsi, lemongrass, dried ginger, mint.') on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, is_featured = excluded.is_featured, is_bestseller = excluded.is_bestseller, search_text = excluded.search_text;
insert into public.products (id, category_id, name, slug, short_description, description, ingredients, origin, storage_instructions, shelf_life, status, is_featured, is_bestseller, search_text) values ('3be7fea5-038f-4d64-a108-ea45369015a9', 'd1878a8e-3d8a-400a-aa16-c7e7c0d06a0f', 'Organic Jaggery Blocks', 'organic-jaggery-blocks', 'Set cane jaggery with mineral depth. No sulphur.', 'Clarified over a wood fire and poured into blocks. Colour varies by harvest — that is expected. Grate into dals, or eat a sliver after meals.', 'Organic sugarcane juice.', NULL, 'Wrap tightly. Softens in humidity — refrigerate if needed.', '12 months', 'published', FALSE, TRUE, 'organic jaggery blocks set cane jaggery with mineral depth. no sulphur. organic sugarcane juice.') on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, is_featured = excluded.is_featured, is_bestseller = excluded.is_bestseller, search_text = excluded.search_text;
insert into public.products (id, category_id, name, slug, short_description, description, ingredients, origin, storage_instructions, shelf_life, status, is_featured, is_bestseller, search_text) values ('48eacc8e-57c8-4944-ae5c-dc5cda173736', '9f275838-5ad7-414c-abf4-16f9ed095b4d', 'Organic Ponni Rice', 'organic-ponni-rice', 'Single-estate Ponni. Soft, everyday rice.', 'Boiled and raw lots from named farm lots. No blending with broken grain from elsewhere. Rinse twice; cook at 1:2. The grain stays separate, with a mild, clean aroma.', 'Organic Ponni rice (Oryza sativa).', NULL, 'Airtight tin, away from moisture. Check in monsoon.', '12 months', 'published', TRUE, TRUE, 'organic ponni rice single-estate ponni. soft, everyday rice. organic ponni rice (oryza sativa).') on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, is_featured = excluded.is_featured, is_bestseller = excluded.is_bestseller, search_text = excluded.search_text;
insert into public.products (id, category_id, name, slug, short_description, description, ingredients, origin, storage_instructions, shelf_life, status, is_featured, is_bestseller, search_text) values ('3a432380-8cb9-4ca2-aa73-7f0d2fc098a8', '9f275838-5ad7-414c-abf4-16f9ed095b4d', 'Organic Finger Millet (Ragi)', 'organic-finger-millet-ragi', 'Whole ragi for porridge, roti, and malt.', 'Unpolished finger millet with bran intact. Earthy flavour, good for everyday breakfast porridge. Wash and soak if grinding at home.', 'Organic finger millet (Eleusine coracana).', NULL, 'Airtight jar. Check for moisture in monsoon.', '10 months', 'published', FALSE, FALSE, 'organic finger millet (ragi) whole ragi for porridge, roti, and malt. organic finger millet (eleusine coracana).') on conflict (slug) do update set name = excluded.name, short_description = excluded.short_description, description = excluded.description, is_featured = excluded.is_featured, is_bestseller = excluded.is_bestseller, search_text = excluded.search_text;
